#include "ControlEdits.h"
#include "ControlMailbox.h"
static void testControl(const File& root){
    auto source=emptyProject();Project next;auto edit=JSON::parse(R"([{"op":"set_song","bpm":76,"songMode":true},{"op":"set_track","track":5,"name":"Deep drone","preset":"Round sub","synth":{"cutoff":650,"wave2":1},"params":{"volume":0.35},"effects":{"reverb":{"mix":0.2}}},{"op":"set_pattern","pattern":0,"name":"Ritual","length":16},{"op":"set_notes","pattern":0,"track":5,"notes":[{"beat":0,"length":8,"pitch":38,"velocity":0.7}]},{"op":"set_arrangement","clips":[{"track":5,"pattern":0,"beat":0,"length":32}]},{"op":"set_markers","markers":[{"id":"ritual","name":"Ritual","beat":0,"endBeat":32,"colour":3}]}])");
    expect(applyControlEdits(source,edit,next).wasOk()&&next.bpm==76&&next.songMode&&next.tracks[5].instrument==Instrument::analog&&next.tracks[5].synth.cutoff==650&&next.patterns[0].length==16&&next.clips.size()==1&&next.markers.size()==1,"atomic control batch designs a sound, writes notes and composes a section");
    auto sentinel=projectToJson(next);auto rejected=[&](const char* json){Project output=next;return applyControlEdits(source,JSON::parse(json),output).failed()&&JSON::toString(projectToJson(output))==JSON::toString(sentinel);};
    for(auto json:{R"([])",R"([{"op":"unknown"}])",R"([{"op":"set_song","bpm":120},{"op":"set_song","bpm":0}])",R"([{"op":"set_song","bpm":"76"}])",R"([{"op":"set_song","loop":1}])",R"([{"op":"set_song","arbitrary":1}])",R"([{"op":"set_track","track":99}])",R"([{"op":"set_track","track":5,"synth":{"cutoff":100000}}])",R"([{"op":"set_track","track":5,"preset":"Round sub","synth":{"unknown":1}}])",R"([{"op":"set_track","track":5,"instrument":"fm","preset":"Round sub"}])",R"([{"op":"set_track","track":5,"params":{"volume":2}}])",R"([{"op":"set_track","track":5,"effects":{"reverb":{"mix":-1}}}])",R"([{"op":"set_notes","pattern":0,"track":5,"notes":[{"beat":8,"length":1,"pitch":60,"velocity":0.8}]}])",R"([{"op":"set_notes","pattern":0,"track":5,"notes":[{"beat":0,"length":1,"pitch":60.5,"velocity":0.8}]}])",R"([{"op":"set_arrangement","clips":[{"track":0,"pattern":99,"beat":0,"length":8}]}])",R"([{"op":"set_markers","markers":[{"id":"same","name":"A","beat":0,"colour":1},{"id":"same","name":"B","beat":1,"colour":1}]}])"})expect(rejected(json),"invalid control batch preserves the entire destination and source");
    auto ops=JSON::parse(R"([{"op":"add_track","name":"Reverb bus","bus":true},{"op":"set_track","track":5,"output":8},{"op":"add_pattern","name":"Other","length":12},{"op":"add_automation","track":0,"target":5,"targetTrack":-1,"beat":0,"length":32,"points":[{"beat":0,"value":0.1},{"beat":32,"value":0.8}]}])");
    expect(applyControlEdits(source,ops,next).wasOk()&&next.tracks.size()==9&&next.tracks[8].isBus&&next.tracks[5].mixer.output==8&&next.patterns[1].lanes.size()==9&&next.clips[0].isAutomation(),"control supports buses, complete lane expansion and automation endpoints");
    Project unchanged=next;expect(applyControlEdits(next,JSON::parse(R"([{"op":"set_track","track":8,"output":5}])"),unchanged).failed()&&unchanged.tracks[8].mixer.output==-1,"control refuses routing feedback atomically");
    expect(applyControlEdits(next,JSON::parse(R"([{"op":"set_notes","pattern":0,"track":8,"notes":[]}])"),unchanged).failed(),"buses cannot silently become note lanes");
    auto originalId=source.patterns[0].editorId;expect(applyControlEdits(source,edit,next).wasOk()&&next.patterns[0].editorId==originalId,"control edits retain existing pattern clipboard identities");
    Assets assets;auto playback=std::make_unique<Playback>();String warnings;expect(compilePlayback(next,assets,root,*playback,warnings).wasOk()&&playback->eventCount==2,"MCP-created pattern clips compile repeated live events");auto audio=render(next,assets,root,48000);expect(audio.getMagnitude(0,0,48000)>.001,"MCP-designed sound and notes render audible audio");
    auto workspace=root.getChildFile("mailbox-core");ControlMailbox mailbox;expect(mailbox.start(workspace).wasOk(),"local control publishes a session without network services");auto metadata=JSON::parse(workspace.getChildFile("data/control/session.json").loadFileAsString());auto token=metadata["token"].toString();auto session=metadata["session"].toString();expect(token.isNotEmpty()&&session.length()==32,"each local control session has its own identity and token");int calls=0;auto handler=[&](const String& command,const var&,var& output){++calls;output=command;return Result::ok();};
    auto request=[&](const String& id,const String& auth,int64 created,int64 expires){auto* o=new DynamicObject();o->setProperty("schema",1);o->setProperty("id",id);o->setProperty("session",session);o->setProperty("token",auth);o->setProperty("createdAt",created);o->setProperty("expiresAt",expires);o->setProperty("command","status");o->setProperty("arguments",var(new DynamicObject()));mailbox.directory().getChildFile("requests/"+id+".json").replaceWithText(JSON::toString(var(o)));mailbox.poll(handler);return JSON::parse(mailbox.directory().getChildFile("responses/"+id+".json").loadFileAsString());};
    auto now=Time::currentTimeMillis();auto id=Uuid().toString().removeCharacters("-");expect((bool)request(id,token,now,now+10000)["ok"]&&calls==1,"mailbox dispatches an authenticated fresh request on the UI producer");request(id,token,now,now+10000);expect(calls==1,"replaying a request identity cannot execute it twice");expect(!(bool)request(Uuid().toString().removeCharacters("-"),"wrong",now,now+10000)["ok"]&&calls==1,"wrong session token cannot mutate the app");expect(!(bool)request(Uuid().toString().removeCharacters("-"),token,now-30000,now-10000)["ok"]&&calls==1,"expired mutations are rejected rather than executed late");
    mailbox.stop();expect(!workspace.getChildFile("data/control/session.json").existsAsFile(),"disabling control invalidates its published session");expect(mailbox.start(workspace).wasOk(),"local control can start a fresh session");auto replaced=JSON::parse(workspace.getChildFile("data/control/session.json").loadFileAsString());expect(replaced["token"].toString()!=token&&replaced["session"].toString()!=session,"re-enabling local control rotates both token and queue");mailbox.stop();
}
